 ## Unreleased

+- Fix batch consumption to use FEFO order (earliest expiry first, null expiry last, then oldest receipt and lowest id) instead of newest receipt first.
 - Show stock on hand in `GET /items`.

 ## 2.3.0 - 2026-10-20
diff --git a/src/domain/batches.js b/src/domain/batches.js
index ee14fde..dfce591 100644
--- a/src/domain/batches.js
+++ b/src/domain/batches.js
@@ -18,9 +18,21 @@ export function getBatch(store, id) {
   return batch;
 }

-// The order in which an item's batches are used up.
+function compareExpiry(a, b) {
+  if (a && b) return a.localeCompare(b);
+  if (a) return -1;
+  if (b) return 1;
+  return 0;
+}
+
+// The order in which an item's batches are used up (FEFO, nulls last, then FIFO, then id).
 function consumptionOrder(batches) {
-  return [...batches].sort((a, b) => b.receivedOn.localeCompare(a.receivedOn));
+  return [...batches].sort(
+    (a, b) =>
+      compareExpiry(a.expires, b.expires) ||
+      a.receivedOn.localeCompare(b.receivedOn) ||
+      a.id - b.id,
+  );
 }

